		// an alias name or index alone never stamps a row.
		if (!harnessId && !modelRef) return null;
		return {
			...(harnessId ? { harnessId } : {}),
			...(modelRef ? { modelRef } : {}),
			...(aliasName ? { aliasName } : {}),
			...(targetIndex !== null ? { targetIndex } : {}),
		};
	} catch {
		return null;
	}
