export function stampArrivalRowAttribution(
	task,
	arrivalLabel,
	attribution = {},
) {
	try {
		const clean = buildTimelineAttribution(attribution);
		if (!clean) return null;
		const label =
			typeof arrivalLabel === "string" && arrivalLabel.trim()
				? arrivalLabel.trim()
