		bridge = taskStore.eventBridge,
		projectCwd,
		fallbackStageId,
		skipFailback = false,
		compactionHint = false,
		harnessId,
		failureKind,
		aliasName,
		modelRef,
		targetIndex,
	} = opts;
	const failureProject = resolveFailureProject(taskStore, projectId, opts);
	const task = taskStore.getTask(projectId, taskId);
	if (!task) return null;
	// WP6 watchdog de-duplication: the stall watchdog already terminated this
	// run and routed it through `handleTransientFailure` with `{ stall: true }`.
	// The terminated child settles with a non-zero exit and would otherwise
	// fail back immediately after the transient retry; suppress that duplicate
	// exactly once.
	if (consumeStallHandled(taskStore, taskId)) {
		return {
			task,
			stageType: stage?.type || "agent",
			status: "stalled",
			message:
				"Stage stall already handled by the watchdog; duplicate failure routing suppressed",
		};
	}
	// Single taxonomy, classified once per failure for auditability.
	const { classification, classificationMeta } = classificationMetaOf(error);
	// Context overflow never parks instantly: it fails back so the next
	// attempt compacts the prompt/history. An explicit compactionHint opts in
	// even when the caller parked unrecoverable errors by default.
	const compactionHintEffective =
		compactionHint === true || classification.signal === "context-overflow";
	const effectiveSkipFailback =
		compactionHint === true ? false : skipFailback;
	// A failure settling after the operator finished the task (complete,
	// fail/park, cancel) must not resurrect it via failback or auto-retry.
	if (isTerminalTaskStatus(task.status)) {
		return {
			task,
			stageType: stage?.type || "agent",
			status: task.status,
			message: `Task is already ${task.status}; failure ignored`,
		};
	}
	// A run aborted by pause settles here: the pause must stick, so neither
	// failback nor auto-retry may move the task back into the queue.
	if (String(task.status).toLowerCase() === "paused") {
		return {
			task,
			stageType: stage?.type || "agent",
			status: "paused",
			message: "Task is paused; failure does not fail back",
		};
	}
	// A run superseded by an operator move settles here: the move already
	// parked the task at its destination, so the orphaned run's outcome must
	// not be attributed to the new stage. Command stages surface the kill as
	// a plain non-zero exit (no operator-abort marker), which would otherwise
	// fail back with a spurious failureReason and auto-retry, undoing the
	// move (task 072e2cfa). Match on the recorded stage so only that orphaned
	// run is quieted; the marker is consumed either way so a later genuine
	// failure in the destination stage routes normally. An unknown failing
	// stage (null) is treated as the orphaned run: the operator's explicit
	// move sticks, and the task parks at its destination where a retry is
	// always available — failing safe toward operator intent, never toward
	// an automatic failback that would undo it.
	if (task.supersededStageId != null) {
		const superseded = String(task.supersededStageId);
		const failingId = stage?.id != null ? String(stage.id) : null;
		const currentId =
			task.currentStageId != null ? String(task.currentStageId) : null;
		delete task.supersededStageId;
		if (
			currentId !== superseded &&
			(failingId === null || failingId === superseded)
		) {
			return settleOperatorAbort(taskStore, projectId, taskId, stage, error, {
				bridge,
				projectCwd,
			});
		}
	}

	// An operator-initiated abort carries no actionable failure: settle
	// quietly without failback, retry, or budget, whatever the status.
	if (classification.kind === "operator-abort") {
		return settleOperatorAbort(taskStore, projectId, taskId, stage, error, {
			bridge,
			projectCwd,
		});
	}

	// Tier-5 gate: record the failure against the trip sensors first (this
	// call may itself trip the engine), then quiet-defer instead of failing
	// back, auto-retrying, or burning any budget while containment holds.
	recordCircuitFailure(taskStore, { taskId, error, failureKind });
	if (isTripped(taskStore)) {
		const deferral = deferForCircuitTrip(taskStore, projectId, taskId, stage, error, {
			bridge,
			projectCwd,
			failureKind,
		});
		if (deferral && !deferral.continueNormalHandling) return deferral;
	}

	// A task parked as interrupted by an engine stop keeps that state so
	// resume/retry starts clean: genuine failures are recorded for feedback
	// but never move the task or spend iteration budget by themselves.
	const wasInterrupted = String(task.status).toLowerCase() === "interrupted";

	const errorMsg =
		typeof error === "string"
			? error
			: error?.message || "Stage execution failed";
	const cwd = taskStore._resolveProjectCwd(projectId, projectCwd);
	const stageType = stage?.type || "agent";
	const stderrText = error?.stderr ? String(error.stderr).trim() : "";
	const stdoutText = error?.stdout ? String(error.stdout).trim() : "";
	task.failureReason = errorMsg;
	task.lastError = {
		message: errorMsg,
		stageId: stage?.id,
		stageName: stage?.name || stage?.id,
		stageType,
		stderr: stderrText,
		stdout: stdoutText,
		...(failureKind ? { failureKind } : {}),
		...(gitDiagnosticsOf(error) ? { gitDiagnostics: gitDiagnosticsOf(error) } : {}),
		classification: classificationMeta,
		...(compactionHintEffective ? { compactionHint: true } : {}),
		timestamp: new Date().toISOString(),
	};
	if (!Array.isArray(task.history)) {
		task.history = [];
	}
	task.history.push({
		timestamp: new Date().toISOString(),
		action: `Stage failed in '${stage?.name || stage?.id || "unknown"}': ${errorMsg}`,
	});
	_appendProcessLog(task, `[ERROR] ${errorMsg}`);
	taskStore._saveTaskMarkdown(cwd, task);

	const failureDuration = stageElapsedSeconds(task);
	// Timeline attribution for the failed run: the resolved harness/model/
	// alias this attempt dispatched through, straight from the routing opts
	// (never a second resolution). A failure with no attribution (command
	// stages, pre-contract runs) spreads nothing — the row stays blank by
	// omission, never placeholder-worded.
	const runAttribution = buildTimelineAttribution({
		harnessId,
		aliasName,
		modelRef,
		targetIndex,
	});
	taskStore._recordTimelineWithDiffStat(
		task,
		{
			stage: stage?.name || stage?.id || task.currentStageId,
			status: "Failed",
			duration: failureDuration === undefined ? "--" : `${failureDuration}s`,
			durationSeconds: failureDuration,
			durationStageId: stage?.id || task.currentStageId,
			durationStartedAt: task.enteredStageAt,
			timestamp: new Date().toISOString(),
			reason: errorMsg,
			stageId: stage?.id,
			stageName: stage?.name || stage?.id,
			classification: classificationMeta,
			...(compactionHintEffective ? { compactionHint: true } : {}),
			...(stderrText ? { stderr: excerptLog(stderrText) } : {}),
			...(stdoutText ? { stdout: excerptLog(stdoutText) } : {}),
			...(runAttribution || {}),
		},
		cwd,
		{ useBranches: isBranchModeEnabled(taskStore.projectStore, projectId) },
	);
	const failureReport = generateStageReportContent({
		task,
		stage,
		output: error?.stdout || errorMsg,
		summary: `Execution failed: ${errorMsg}`,
		status: "FAILED",
		duration: stageElapsedSeconds(task),
		error: errorMsg,
	});

	taskStore.saveStageReport(projectId, taskId, {
		stageName: stage?.name || stage?.id || "Stage",
		stageId: stage?.id,
		duration: stageElapsedSeconds(task),
		status: "FAILED",
		content: failureReport,
		projectCwd: cwd,
		harnessId,
		failureKind,
		aliasName,
		modelRef,
		targetIndex,
		// Failure traces keep the `-failure-` filename infix so they stay
		// distinguishable from opt-in success reports in the docs folder.
		failure: true,
	});

	// The user-facing error toast is NOT emitted here: at this point routing
	// does not know yet whether the failure auto-retries or fails back into
	// continued work. Toasting unconditionally pages the operator for
	// failures that recover on their own. The toast fires below, only when
	// the task actually parks without automatic recovery.
	bridge?.emitSystemLog?.(
		projectId,
		`[CLASSIFY] Stage '${stage?.name || stage?.id}' error on task #${task.id?.slice(0, 4)}: kind=${classificationMeta.kind} signal=${classificationMeta.signal} retryable=${classificationMeta.retryable}`,
		{ taskId, stageId: stage?.id, classification: classificationMeta },
	);
	bridge?.emitSystemLog?.(
		projectId,
		`[ERROR] Stage '${stage?.name || stage?.id}' failed on task #${task.id?.slice(0, 4)}: ${errorMsg}`,
		{ taskId, stageId: stage?.id, error: errorMsg, classification: classificationMeta },
	);

	bridge?.emitProcessEvent?.(projectId, "process:stderr", {
		taskId,
		chunk: errorMsg,
		projectName: projectId,
	});
	bridge?.emitProcessEvent?.(projectId, "process:exit", {
		taskId,
		stageId: stage?.id,
		exitCode: typeof error?.code === "number" ? error.code : 1,
		status: "failed",
		error: errorMsg,
		projectName: projectId,
	});

	if (!effectiveSkipFailback && !wasInterrupted) {
		const fallbackTarget =
			fallbackStageId || stage?.fallbackStageId || stage?.failback;
		bridge?.emitProcessEvent?.(projectId, "stage:failback", {
			taskId,
			fromStageId: stage?.id,
			targetStageId: fallbackTarget || task.currentStageId,
			error: errorMsg,
			projectName: projectId,
			classification: classificationMeta,
			...(compactionHintEffective ? { compactionHint: true } : {}),
		});

		taskStore.failbackStage(projectId, taskId, stages, fallbackTarget, bridge, cwd);

		task.failureReason = errorMsg;
		task.lastError = {
			message: errorMsg,
			stageId: stage?.id,
			stageName: stage?.name || stage?.id,
			stageType,
			stderr: stderrText,
			stdout: stdoutText,
			...(failureKind ? { failureKind } : {}),
			...(gitDiagnosticsOf(error) ? { gitDiagnostics: gitDiagnosticsOf(error) } : {}),
			classification: classificationMeta,
			...(compactionHintEffective ? { compactionHint: true } : {}),
			timestamp: new Date().toISOString(),
		};
	}

	const autoIteration =
		effectiveSkipFailback || wasInterrupted
			? null
			: beginAutoIteration(task, stage, errorMsg, failureProject);
	if (autoIteration) {
		// Early warning before the budget runs out: edge-triggered per
		// threshold, detached so a dead sink never slows the retry.
		void maybeEmitFailbackWarning(bridge, {
			projectId,
			task,
			stage,
			attempt: task.autoIterationCount,
			maxAttempts: autoIteration.maxAttempts,
			error: errorMsg,
		});
		taskStore._saveTaskMarkdown(cwd, task);
		const targetStage = stages.find(
			(s) =>
				String(s.id) === String(task.currentStageId) ||
				(s.name &&
					String(s.name).toLowerCase() ===
						String(task.currentStageId).toLowerCase()),
		);
		bridge?.emitProcessEvent?.(projectId, "stage:auto_retry", {
			taskId,
			fromStageId: stage?.id,
			targetStageId: task.currentStageId,
			targetStageName: targetStage?.name || task.currentStageId,
			attempt: task.autoIterationCount,
			maxAttempts: autoIteration.maxAttempts,
			error: errorMsg,
			projectName: projectId,
		});
		bridge?.emitSystemLog?.(
			projectId,
			`[AUTO] Stage '${stage?.name || stage?.id}' failed on task #${task.id?.slice(0, 4)}; auto-retrying at '${targetStage?.name || task.currentStageId}' (attempt ${task.autoIterationCount}/${autoIteration.maxAttempts}): ${errorMsg}`,
			{ taskId, stageId: stage?.id, error: errorMsg },
		);
		if (taskStore.schedulerRunning) {
			setTimeout(() => {
				taskStore.scheduleTick().catch(() => {});
			}, 2000);
		}
		return {
			task,
			stageType,
			status: "retrying",
			error: errorMsg,
			failureReason: errorMsg,
			autoIteration: true,
			attempt: task.autoIterationCount,
			maxAttempts: autoIteration.maxAttempts,
			exitCode: typeof error?.code === "number" ? error.code : 1,
		};
	}

	const parkedFrom = wasInterrupted ? "interrupted" : task.status;
	if (!wasInterrupted) {
		task.status = "failed";
	}
	taskStore._saveTaskMarkdown(cwd, task);

	// Human-intervention push: the task is parked and auto-recovery cannot
	// proceed (unrecoverable error, exhausted budget, or failback-skipped
	// land). Normal CI failures that fail back, deliberate rejections, and
	// human-checkpoint parks stay silent. Best-effort: never breaks routing.
	if (!wasInterrupted) {
		// User-facing error toast: the task parked without automatic
		// recovery, so this genuinely needs the operator. Skipped for
		// auto-retries and failback continuations (those recover on their
		// own and surface their own retry/failback events).
		bridge?.emitNotification?.(projectId, {
			type: "error",
			title: `Stage "${stage?.name || stage?.id}" Failed`,
			message: errorMsg,
			taskId,
			stageId: stage?.id,
		});
		const pushReason = resolveStageErrorPushReason({
			task,
			parkedFrom,
			stage,
			error,
			failureKind,
			failureProject,
			skipFailback: effectiveSkipFailback,
		});
		if (pushReason) {
			fireStageErrorPush(taskStore, {
				projectId,
				taskId,
				stage,
				error: errorMsg,
				reason: pushReason,
			});
		}
		// Outbound alert: an unscheduled park is `failed`/`critical`, never
		// confused with a scheduled `waiting_human` checkpoint. Detached so
		// an unreachable sink settles the task identically. The WP2
		// classification (already computed for the timeline) supplies the
		// precise signal, so the payload and the audit trail cannot disagree.
		const parkedKind = classificationMeta.kind;
		const parkedSeverity = resolveAlertSeverity("failed", parkedKind);
		// Project-blocker dedupe (C3): one red shared gate parks N tasks, but
		// only the FIRST park per gate@sha emits the project-level alert —
		// later parks record the same reason in history/timeline without
		// re-alerting. Best-effort and in-memory (a restart may re-alert
		// once); never breaks routing.
		let suppressParkedAlert = false;
		try {
			suppressParkedAlert = shouldSuppressProjectBlockerAlert(
				taskStore,
				error?.projectBlocker?.key,
				{ taskId, projectId },
			);
		} catch {
			suppressParkedAlert = false;
		}
		if (parkedSeverity && !suppressParkedAlert) {
			void emitAlert(bridge, {
				event: "task.failed",
				severity: parkedSeverity,
				projectId,
				taskId,
				stage: { id: stage?.id, name: stage?.name || stage?.id, type: stageType },
				kind: parkedKind,
				signal: classificationMeta.signal,
				message: errorMsg,
				excerpt: excerptLog(
					[errorMsg, stderrText, stdoutText].filter(Boolean).join("\n"),
				),
				attemptCounts: {
					transient: task.infraRetryCount || 0,
					autoIteration: task.autoIterationCount || 0,
				},
				...parkedAlertStructuredFields(task, error),
			});
		}
	}

	return {
		task,
		stageType,
		status: task.status,
		error: errorMsg,
		failureReason: errorMsg,
		exitCode: typeof error?.code === "number" ? error.code : 1,
	};
}

import {
	config,
} from "../../../config.js";
import {
	_appendProcessLog,
} from "../../../watch/index.js";
import {
	emitAlert,
	resolveAlertSeverity,
	resolveErrorClassification,
} from "../../../observability/alerts.js";
import {
	isTerminalTaskStatus,
	stageElapsedSeconds,
} from "../../stagePolicy.js";
import {
	consumeStallHandled,
} from "../../stageHeartbeat.js";
import {
	isTripped,
} from "../../circuitBreaker.js";
import {
	recordCircuitFailure,
} from "../../circuitSensors.js";
import {
	buildTimelineAttribution,
} from "../../runAttribution.js";
import {
	classificationMetaOf,
	computeRetryDelay,
	excerptLog,
	fireStageErrorPush,
	resolveFailureProject,
	resolveRetryable,
	resolveTransientBudget,
} from '../resolvers/index.js';
import { settleOperatorAbort } from './settleOperatorAbort.js';
import { deferForCircuitTrip } from './deferForCircuitTrip.js';
import { handleStageFailure } from './handleStageFailure.js';
import { recordTransientAttemptReport } from './recordTransientAttemptReport.js';

/***
 * MARK: handleTransientFailure
 * @description Handles transient infrastructure failures by retrying the SAME stage instead of failback routing.
 * @param {Object} taskStore - TaskStore instance.
 * @param {string} projectId
 * @param {string} taskId
 * @param {Object} stage
 * @param {Error|string} error
 * @param {Object} [opts]
 * @param {Object} [opts.bridge]
 * @param {string} [opts.projectCwd]
 * @param {string} [opts.harnessId] - Harness that ran the failed attempt (reliability attribution; a FAILED report is recorded only when present with the infrastructure kind).
 * @param {string} [opts.failureKind] - Runner outcome kind (must be "infrastructure" for the attempt report).
 * @param {string} [opts.aliasName] - Model alias the failed attempt resolved through (per-alias reliability attribution).
 * @param {string} [opts.modelRef] - Concrete model the alias target dispatched.
 * @param {number} [opts.targetIndex] - Weighted-target index of the alias pick (informational).
 * @param {Object} [opts.retryDelay] - Per-call delay overrides (`baseMs`, `capMs`, `jitterMs`, `strategy`; WP10 fault-injection seam).
 * @param {Function} [opts.retryRand] - Injectable uniform [0,1) source for jitter (deterministic tests; default `Math.random`).
 * @returns {Object} Retry or parked-failure result.
  * @example handleTransientFailure(store, "p1", "t1", stage, err, {}) => { status: "in_stage", … }
 ***/
export function handleTransientFailure(
	taskStore,
	projectId,
	taskId,
	stage,
	error,
	opts = {},
) {
	const {
		bridge = taskStore.eventBridge,
		projectCwd,
		harnessId,
		failureKind,
		aliasName,
		modelRef,
		targetIndex,
		retryDelay,
		retryRand,
	} = opts;
	const failureProject = resolveFailureProject(taskStore, projectId, opts);
	const task = taskStore.getTask(projectId, taskId);
	if (!task) return null;
	// WP6 watchdog de-duplication: see `handleStageFailure`. The watchdog's own
	// routing runs BEFORE the marker is set, so this only suppresses the
	// duplicate emitted by the terminated in-flight run.
	if (consumeStallHandled(taskStore, taskId)) {
		return {
			task,
			stageType: stage?.type || "agent",
			status: task.status,
			message:
				"Stage stall already handled by the watchdog; duplicate transient routing suppressed",
		};
	}
	const { classification, classificationMeta } = classificationMetaOf(error);
	// A transient error settling after the task finished must not flip it
	// back to in_stage for another retry.
	if (isTerminalTaskStatus(task.status)) {
		return {
			task,
			stageType: stage?.type || "agent",
			status: task.status,
			message: `Task is already ${task.status}; transient failure ignored`,
		};
	}
	// Same for a paused task: no retry flip, no budget consumed.
	if (String(task.status).toLowerCase() === "paused") {
		return {
			task,
			stageType: stage?.type || "agent",
			status: "paused",
			message: "Task is paused; transient failure does not retry",
		};
	}

	// An operator-initiated abort carries no actionable failure: settle
	// quietly without retry or budget, whatever the status.
	if (classification.kind === "operator-abort") {
		return settleOperatorAbort(taskStore, projectId, taskId, stage, error, {
			bridge,
			projectCwd,
		});
	}

	// Tier-5 gate: record the infrastructure failure against the trip sensors
	// (this call may itself trip the engine), then quiet-defer instead of
	// incrementing `infraRetryCount` or flipping the task back to `in_stage`.
	recordCircuitFailure(taskStore, { taskId, error, failureKind });
	if (isTripped(taskStore)) {
		const deferral = deferForCircuitTrip(taskStore, projectId, taskId, stage, error, {
			bridge,
			projectCwd,
			failureKind,
		});
		if (deferral && !deferral.continueNormalHandling) return deferral;
	}

	// A task parked as interrupted by an engine stop keeps that state so
	// resume/retry starts clean: record the failure for feedback but never
	// flip it back to in_stage or spend retry budget by itself.
	if (String(task.status).toLowerCase() === "interrupted") {
		const interruptedMsg =
			typeof error === "string" ? error : error?.message || "Transient infrastructure failure";
		const interruptedCwd = taskStore._resolveProjectCwd(projectId, projectCwd);
		task.failureReason = interruptedMsg;
		task.lastError = {
			message: interruptedMsg,
			stageId: stage?.id,
			stageName: stage?.name || stage?.id,
			stageType: stage?.type || "agent",
			classification: classificationMeta,
			timestamp: new Date().toISOString(),
		};
		task.autoRetrying = false;
		if (!Array.isArray(task.history)) {
			task.history = [];
		}
		task.history.push({
			timestamp: new Date().toISOString(),
			action: `Transient infrastructure error in '${stage?.name || stage?.id || "unknown"}' while interrupted: ${interruptedMsg} — awaiting resume/retry`,
		});
		taskStore._saveTaskMarkdown(interruptedCwd, task);
		return {
			task,
			stageType: stage?.type || "agent",
			status: "interrupted",
			message: "Task is interrupted; transient failure does not retry",
		};
	}

	const errorMsg =
		typeof error === "string"
			? error
			: error?.message || "Transient infrastructure failure";
	const cwd = taskStore._resolveProjectCwd(projectId, projectCwd);
	const stageType = stage?.type || "agent";
	const stageLabel = stage?.name || stage?.id || "unknown";
	const { maxAttempts, source: budgetSource } = resolveTransientBudget(stage, failureProject);
	task.infraRetryCount = (task.infraRetryCount || 0) + 1;
	const attempt = task.infraRetryCount;
	// WP3 retryable signal: the WP2 signal when infrastructure-classified,
	// otherwise the matched harness-blip signal (deny-listed errors never
	// reach this handler via resolveRetryable, but resolve it anyway so the
	// ladder always names what was matched).
	const retrySignal = resolveRetryable(error).signal || classificationMeta.signal;
	const budgetNote = `budget ${maxAttempts} from ${budgetSource === "stage" ? "stage.maxTransientRetries" : budgetSource === "project" ? "project.maxTransientRetries" : "global config"}`;
	if (!Array.isArray(task.transientRetryLadder)) {
		task.transientRetryLadder = [];
	}

	if (attempt > maxAttempts) {
		const ladderLines = task.transientRetryLadder.map(
			(entry) => `attempt ${entry.attempt}/${maxAttempts}: ${entry.delayMs}ms [${entry.signal}] ${entry.error}`,
		);
		const ladderText = ladderLines.length > 0 ? ` Retry ladder: ${ladderLines.join(" | ")}.` : "";
		task.failureReason = errorMsg;
		task.lastError = {
			message: errorMsg,
			stageId: stage?.id,
			stageName: stage?.name || stage?.id,
			stageType,
			classification: classificationMeta,
			transientBudget: { maxAttempts, source: budgetSource },
			retryLadder: [...task.transientRetryLadder],
			timestamp: new Date().toISOString(),
		};
		task.status = "failed";
		task.autoRetrying = false;
		if (!Array.isArray(task.history)) {
			task.history = [];
		}
		task.history.push({
			timestamp: new Date().toISOString(),
			action: `Stage '${stageLabel}' parked after ${maxAttempts} transient-failure retries (${budgetNote}): ${errorMsg}.${ladderText}`,
		});
		_appendProcessLog(
			task,
			`[ERROR] Stage '${stageLabel}' still unreachable after ${maxAttempts} retries (${budgetNote}); parked for human intervention. Last error: ${errorMsg}.${ladderText}`,
		);
		taskStore._recordTimelineWithDiffStat?.(
			task,
			{
				stage: stage?.name || stage?.id || task.currentStageId,
				status: "Failed",
				duration: stageElapsedSeconds(task) === undefined ? "--" : `${stageElapsedSeconds(task)}s`,
				timestamp: new Date().toISOString(),
				reason: `Transient retries exhausted (${attempt - 1}/${maxAttempts}, ${budgetNote}): ${errorMsg}.${ladderText}`,
				stageId: stage?.id,
				stageName: stage?.name || stage?.id,
				classification: classificationMeta,
				signal: retrySignal,
				maxAttempts,
				budgetSource,
				retryLadder: [...task.transientRetryLadder],
				...(buildTimelineAttribution({
					harnessId,
					aliasName,
					modelRef,
					targetIndex,
				}) || {}),
			},
			cwd,
		);
		recordTransientAttemptReport(
			taskStore,
			projectId,
			taskId,
			stage,
			errorMsg,
			`Transient infrastructure error persisted after ${maxAttempts} retries (${budgetNote}): ${errorMsg}.${ladderText}`,
			cwd,
			harnessId,
			failureKind,
			{ aliasName, modelRef, targetIndex },
		);
		taskStore._saveTaskMarkdown(cwd, task);
		// Transient budget exhausted: the stage is parked and cannot
		// auto-recover — this always needs a human. Best-effort hook.
		fireStageErrorPush(taskStore, {
			projectId,
			taskId,
			stage,
			error: errorMsg,
			reason: "transient_retries_exhausted",
		});
		// Outbound alert: persistent infrastructure exhaustion parks the task
		// for a human (`failed`/`critical`). Detached: a dead sink parks
		// the task exactly the same way. The kind is classified (not
		// hardcoded) so an operator abort that reaches this path settles
		// quietly instead of paging.
		const exhausted = resolveErrorClassification(error);
		const exhaustedSeverity = resolveAlertSeverity("failed", exhausted.kind);
		if (exhaustedSeverity) {
			void emitAlert(bridge, {
				event: "task.failed",
				severity: exhaustedSeverity,
				projectId,
				taskId,
				stage: { id: stage?.id, name: stage?.name || stage?.id, type: stageType },
				kind: exhausted.kind,
				signal: exhausted.signal,
				message: errorMsg,
				excerpt: excerptLog(errorMsg),
				attemptCounts: { attempt, maxAttempts },
			});
		}
		bridge?.emitNotification?.(projectId, {
			type: "error",
			title: `Stage "${stageLabel}" Unreachable`,
			message: `Gave up after ${maxAttempts} retries: ${errorMsg}`,
			taskId,
			stageId: stage?.id,
		});
		bridge?.emitSystemLog?.(
			projectId,
			`[ERROR] Stage '${stageLabel}' failed on task #${task.id?.slice(0, 4)} with a persistent infrastructure error after ${maxAttempts} retries; parked: ${errorMsg}`,
			{ taskId, stageId: stage?.id, error: errorMsg },
		);
		bridge?.emitProcessEvent?.(projectId, "process:exit", {
			taskId,
			stageId: stage?.id,
			exitCode: typeof error?.code === "number" ? error.code : 1,
			status: "failed",
			error: errorMsg,
			projectName: projectId,
		});
		return {
			task,
			stageType,
			status: "failed",
			error: errorMsg,
			failureReason: errorMsg,
			retrySameStage: true,
			attempt,
			maxAttempts,
			budgetSource,
			signal: retrySignal,
			retryLadder: [...task.transientRetryLadder],
			exitCode: typeof error?.code === "number" ? error.code : 1,
		};
	}

	const nextDelayMs = computeRetryDelay(attempt, retryDelay, retryRand);
	task.transientRetryLadder.push({
		attempt,
		delayMs: nextDelayMs,
		signal: retrySignal,
		error: errorMsg,
		timestamp: new Date().toISOString(),
	});
	task.failureReason = null;
	task.lastError = null;
	task.status = "in_stage";
	task.autoRetrying = true;
	if (!Array.isArray(task.history)) {
		task.history = [];
	}
	task.history.push({
		timestamp: new Date().toISOString(),
		action: `Transient infrastructure error in '${stageLabel}' (attempt ${attempt}/${maxAttempts}, ${budgetNote}, next delay ${nextDelayMs}ms, signal ${retrySignal}): ${errorMsg} — retrying same stage`,
	});
	_appendProcessLog(
		task,
		`[WARN] Transient infrastructure error in stage '${stageLabel}' (attempt ${attempt}/${maxAttempts}, ${budgetNote}, next delay ${nextDelayMs}ms, signal ${retrySignal}): ${errorMsg} — retrying same stage`,
	);
	taskStore._recordTimelineWithDiffStat?.(
		task,
		{
			stage: stage?.name || stage?.id || task.currentStageId,
			status: "Retrying",
			duration: stageElapsedSeconds(task) === undefined ? "--" : `${stageElapsedSeconds(task)}s`,
			timestamp: new Date().toISOString(),
			reason: `Transient error (attempt ${attempt}/${maxAttempts}, ${budgetNote}, next delay ${nextDelayMs}ms, signal ${retrySignal}): ${errorMsg} — retrying same stage`,
			stageId: stage?.id,
			stageName: stage?.name || stage?.id,
			classification: classificationMeta,
			signal: retrySignal,
			attempt,
			maxAttempts,
			nextDelayMs,
			budgetSource,
			...(buildTimelineAttribution({
				harnessId,
				aliasName,
				modelRef,
				targetIndex,
			}) || {}),
		},
		cwd,
	);
	recordTransientAttemptReport(
		taskStore,
		projectId,
		taskId,
		stage,
		errorMsg,
		`Transient infrastructure error (attempt ${attempt}/${maxAttempts}, ${budgetNote}, next delay ${nextDelayMs}ms, signal ${retrySignal}): ${errorMsg} — retrying same stage`,
		cwd,
		harnessId,
		failureKind,
		{ aliasName, modelRef, targetIndex },
	);
	taskStore._saveTaskMarkdown(cwd, task);
	bridge?.emitProcessEvent?.(projectId, "stage:retry", {
		taskId,
		stageId: stage?.id,
		stageName: stage?.name || stage?.id,
		sameStage: true,
		transient: true,
		attempt,
		maxAttempts,
		nextDelayMs,
		signal: retrySignal,
		budgetSource,
		error: errorMsg,
		projectName: projectId,
		classification: classificationMeta,
	});
	bridge?.emitSystemLog?.(
		projectId,
		`[RETRY] Stage '${stageLabel}' hit a transient infrastructure error on task #${task.id?.slice(0, 4)}; retrying same stage (attempt ${attempt}/${maxAttempts}, ${budgetNote}, next delay ${nextDelayMs}ms, signal ${retrySignal}): ${errorMsg}`,
		{ taskId, stageId: stage?.id, error: errorMsg, classification: classificationMeta, nextDelayMs, signal: retrySignal, budgetSource },
	);
	if (taskStore.schedulerRunning) {
		setTimeout(() => {
			taskStore.scheduleTick().catch(() => {});
		}, nextDelayMs);
	}
	return {
		task,
		stageType,
		status: "retrying",
		error: errorMsg,
		failureReason: errorMsg,
		autoIteration: true,
		retrySameStage: true,
		attempt,
		maxAttempts,
		nextDelayMs,
		budgetSource,
		signal: retrySignal,
		exitCode: typeof error?.code === "number" ? error.code : 1,
	};
}

	reviewComments = [],
) {
	const task = store.getTask(projectId, taskId);
	if (!task) return null;
	const cleanFeedback = String(feedback || "").trim();
	const stage = stages.find(
		(item) => String(item.id) === String(task.currentStageId),
	);
	store.saveStageReport(projectId, taskId, {
		stageName: stage?.name || task.currentStageId,
		stageId: task.currentStageId,
		duration: stageElapsedSeconds(task),
		status: "FAILED",
		content: `${AUTO_REPORT_MARKER}\n${buildHumanRejectionContent({
			feedback: cleanFeedback,
			comments: reviewComments,
		})}`,
		projectCwd,
	});

	task.feedback = cleanFeedback;
	store._resetAutoIteration(task);
	if (cleanFeedback) {
		task.goal = `${task.goal}\n\n## Human Correction / Feedback\n${cleanFeedback}`;
		task.body = task.goal;
	}
	const rejectionReason = cleanFeedback || "No feedback";
	task.failureReason = rejectionReason;
	task.lastError = {
		message: rejectionReason,
		stageId: stage?.id,
		stageName: stage?.name || stage?.id,
		stageType: stage?.type || "human",
		failureKind: "rejected",
		timestamp: new Date().toISOString(),
	};
	task.history.push({
		timestamp: new Date().toISOString(),
		action: `Rejected by human review: ${cleanFeedback || "No feedback"}`,
	});
	// The timeline carries the structured reason (same shape as agent
	// failures in stageFailureRouting) so the history timeline renders the
	// rejection note instead of a silent failback row.
	const rejectionDuration = stageElapsedSeconds(task);
	store._recordTimelineWithDiffStat(
		task,
		{
			stage: stage?.name || stage?.id || task.currentStageId,
			status: "Failed",
			duration:
				rejectionDuration === undefined ? "--" : `${rejectionDuration}s`,
			durationSeconds: rejectionDuration,
			durationStageId: stage?.id || task.currentStageId,
			durationStartedAt: task.enteredStageAt,
			timestamp: new Date().toISOString(),
			reason: cleanFeedback || "No feedback",
			stageId: stage?.id,
			stageName: stage?.name || stage?.id,
		},
		projectCwd,
		{ useBranches: isBranchModeEnabled(store.projectStore, projectId) },
	);
	_appendProcessLog(
		task,
		`[HUMAN] Rejected by human review: ${cleanFeedback || "No feedback"}`,
	);
	store._saveTaskMarkdown(projectCwd, task);

	const failedBackTask = store.failbackStage(
		projectId,
		taskId,
		stages,
		null,
		bridge,
		projectCwd,
	);
	// Every stage transition clears failure context, so re-apply the
	// rejection after the failback: the task keeps its REJECTED flag and
	// reason banner while staying agent-ready for the next pickup.
	const settledTask = failedBackTask || task;
	settledTask.failureReason = rejectionReason;
	settledTask.lastError = {
		message: rejectionReason,
		stageId: stage?.id,
		stageName: stage?.name || stage?.id,
		stageType: stage?.type || "human",
		failureKind: "rejected",
		timestamp: new Date().toISOString(),
	};
	store._saveTaskMarkdown(projectCwd, settledTask);
	return failedBackTask;

import { git } from "../../git.js";
import {
	isValidReviewBaseline,
	shouldResetReviewBaseline,
} from "../../work/taskBranches.js";
import {
	finalizePassedCommandStage,
	isMergeLanded,
} from "../commandStages.js";
import { _appendProcessLog } from "../../watch/index.js";
import { recordReliabilitySample } from "../../watch/reliabilityShared.js";

/***
 * MARK: applyIntegrationReport
 * @description Engine-owned finish for a Runner-run integration (Step 4):
 *   the integration Runner merged `origin/<taskBranch>` into the target in
 *   an ephemeral worktree and CAS-pushed the target. The backend verifies
 *   read-only (fetch + ancestry — never a checkout, merge, or push), freezes
 *   the PR-review baseline from the reported SHAs, saves the merge report,
 *   and advances. A verification failure parks the task `failed` on the
 *   merge stage (`skipFailback`, sync-blocked diagnostic) instead of
 *   rewinding a merge that may have landed.
 * @example await applyIntegrationReport({ store, projectStore, projectId: 'p', taskId: 't', stage, stages, integration: { mergeSha: 'a', ... } }) => { advanced: true }
 * @param {Object} args - Context.
 * @param {Object} args.store - Task store.
 * @param {Object} args.projectStore - Project store.
 * @param {string} args.projectId - Project id.
 * @param {string} args.taskId - Task id.
 * @param {Object} args.stage - Resolved merge stage.
 * @param {Array} [args.stages] - Full stage list.
 * @param {Object} args.integration - Runner report (`mergeSha`, `targetBranch`, `taskBranch`, `expectedTaskSha`, `expectedTargetSha`, `mergeAttemptId`).
 * @param {string} [args.runnerId] - Reporting Runner.
 * @returns {Promise<Object>} `{ advanced, ... }`.
 ***/
export async function applyIntegrationReport({
	store,
	projectStore,
	projectId,
	taskId,
	stage,
	stages = [],
	integration,
	runnerId = null,
}) {
	const task = store.getTask(projectId, taskId);
	if (!task) {
		const err = new Error(`Task ${taskId} not found`);
		err.statusCode = 404;
		err.code = "TASK_NOT_FOUND";
		throw err;
	}
	const project = projectStore?.getProject?.(projectId);
	const cwd = project?.cwd;
	const bridge = store.eventBridge;
	const taskShortId = String(task.id).slice(0, 4).toUpperCase();
	const via = runnerId ? `via Runner ${runnerId}` : "via Runner";
	const { mergeSha, targetBranch, taskBranch, expectedTaskSha, expectedTargetSha, mergeAttemptId } = integration || {};

	const parkUnverifiable = (message, diagnostics) => {
		const err = new Error(message);
		err.gitDiagnostics = { kind: "sync-blocked", ...(diagnostics || {}) };
		_appendProcessLog(task, `[ERROR] ${message}`);
		try {
			store._saveTaskMarkdown(cwd, task);
		} catch {
			// Parking matters more than the warning.
		}
		return store.handleStageFailure(projectId, taskId, stage, err, {
			stages,
			bridge,
			projectCwd: cwd,
			skipFailback: true,
		});
	};

	if (!mergeSha || !targetBranch || !taskBranch) {
		return parkUnverifiable(
			`Integration report from ${via} is missing mergeSha/targetBranch/taskBranch — cannot verify the merge; retry the merge stage.`,
			{ taskBranch, mainBranch: targetBranch },
		);
	}

	// Idempotent re-entry: a landed marker for this stage means a duplicate
	// report (retry, resume) must not advance twice.
	if (isMergeLanded(task, { stageId: stage?.id })) {
		_appendProcessLog(task, `[MERGE] Duplicate integration report for '${taskBranch}' ignored (merge already landed ${task.reviewBaseline?.mergedAt || "previously"})`);
		try {
			store._saveTaskMarkdown(cwd, task);
		} catch {
			// Advisory only.
		}
		return { advanced: false, status: "passed", duplicate: true };
	}

	// Read-only verification: fetch, then prove the merge commit is an
	// ancestor of the remote target tip. The backend never checks out,
	// merges, or pushes here.
	let targetTip = null;
	let landed = false;
	try {
		await git(cwd, ["fetch", "origin"], { timeout: 60000 });
		targetTip = (await git(cwd, ["rev-parse", "--verify", `origin/${targetBranch}`])).stdout.trim() || null;
		if (targetTip) {
			await git(cwd, ["merge-base", "--is-ancestor", mergeSha, targetTip]);
			landed = true;
		}
	} catch {
		landed = false;
	}
	if (!landed) {
		return parkUnverifiable(
			`Integration of '${taskBranch}' reported merge ${String(mergeSha).slice(0, 7)} by ${via}, but the backend cannot find it on 'origin/${targetBranch}' (tip ${targetTip ? targetTip.slice(0, 7) : "unknown"}) — the push may not have stuck. Retry the merge stage to re-verify; a landed merge is never rewound.`,
			{ taskBranch, mainBranch: targetBranch, sourceSha: mergeSha, targetSha: targetTip },
		);
	}

	// Freeze the PR-review baseline from the reported SHAs (same shape as
	// the embedded merge path; keep-first projects keep their baseline).
	const mergedAt = new Date().toISOString();
	const existing = isValidReviewBaseline(task.reviewBaseline) ? task.reviewBaseline : null;
	if (!(existing && !shouldResetReviewBaseline(project))) {
		const baseline = {
			baseSha: expectedTargetSha || targetTip,
			headSha: expectedTaskSha || mergeSha,
			mainSha: mergeSha,
			mergedAt,
			stageId: stage?.id || null,
		};
		task.reviewBaseline = baseline;
		task.history.push({
			timestamp: mergedAt,
			action: `Recorded PR-review baseline for '${taskBranch}' at Runner-run merge into '${targetBranch}' (${String(mergeSha).slice(0, 7)})`,
		});
		if (typeof store.updateTask === "function" && task.id) {
			store.updateTask(projectId, taskId, { reviewBaseline: baseline }, cwd);
		}
	}
	task.mergeAttemptId = mergeAttemptId || task.mergeAttemptId;
	task.preMergeMainSha = expectedTargetSha || task.preMergeMainSha;
	task.pendingPushVerification = {
		sha: mergeSha,
		branch: targetBranch,
		verified: true,
		verifiedAt: mergedAt,
		verifiedBy: runnerId || "backend-fetch",
	};

	const at = Date.now();
	recordReliabilitySample(store, projectId, taskId, {
		harnessId: "integration",
		failureKind: "none",
		at,
		atRaw: new Date(at).toISOString(),
		stageId: stage?.id,
	});
	bridge?.emitSystemLog?.(
		projectId,
		`[GIT] Task #KB-${taskShortId}: Runner-run merge landed '${taskBranch}' into '${targetBranch}' (${String(mergeSha).slice(0, 7)} ${via})`,
		{ taskId },
	);

	const reportContent = [
		`# Merge Stage Report: ${stage?.name || stage?.id || "merge"}`,
		`**Task branch:** ${taskBranch}`,
		`**Main branch:** ${targetBranch}`,
		`**Status:** PASSED`,
		`**Merge SHA:** ${mergeSha}`,
		`**Landed at:** ${mergedAt}`,
		`**Integrated by:** ${via} (leased integration, ephemeral worktree)`,
	].join("\n");

	const result = await finalizePassedCommandStage(store, projectId, taskId, stage, {
		stages,
		cwd,
		bridge,
		kind: "merge",
		label: "Merge",
		reportContent,
		historyAction: `Merge stage passed: '${taskBranch}' integrated into '${targetBranch}' by ${via}`,
	});
	_appendProcessLog(task, `[MERGE] Verified Runner-run merge ${String(mergeSha).slice(0, 7)} on 'origin/${targetBranch}' and advanced`);
	try {
		store._saveTaskMarkdown(cwd, task);
	} catch {
		// Finalize already persisted what matters.
	}
	return { ...result, advanced: true, mergeSha, verified: true };
}
